 state=load(); selected=state.heroes.find(h=>h.hp>0)?.id||null;
 function save(){try{localStorage.setItem(SAVE,JSON.stringify(state))}catch(e){}}
 function note(msg){let n=$('#boardNote');n.textContent=msg;n.classList.add('show');clearTimeout(note.t);note.t=setTimeout(()=>n.classList.remove('show'),2100)}
 function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),1700)}
