 function addLog(text){log.unshift(text);log=log.slice(0,20);$('#logList').innerHTML=log.map(x=>`<li>${x}</li>`).join('')}
 function units(){return [...state.heroes,...state.enemies].filter(u=>u.hp>0)}
 function at(x,y){return units().find(u=>u.x===x&&u.y===y)}
 function selectedUnit(){return state.heroes.find(h=>h.id===selected&&h.hp>0)}

