  $('#roster').innerHTML=state.heroes.map(h=>`<article class="hero-card ${h.id===selected?'chosen':''} ${h.hp<=0?'down':''}" data-hero="${h.id}"><div class="hero-head"><span class="face">${h.icon}</span><strong>${h.name}</strong></div><small>${h.role}</small><div class="hero-stats"><span>❤ ${Math.max(0,h.hp)}/${h.max}</span><span>⚔ ${h.atk}</span></div><div class="tinybar"><i style="width:${Math.max(0,h.hp/h.max*100)}%"></i></div></article>`).join('');
  document.querySelectorAll('.hero-card').forEach(c=>c.onclick=()=>{if(state.phase!=='hero')return;selected=c.dataset.hero;render()});$('#endTurnBtn').disabled=state.phase!=='hero';$('#endTurnBtn').style.opacity=state.phase==='hero'?'1':'.55';$('#hint').textContent=state.phase==='hero'?(action==='move'?'Подсвеченные клетки — куда можно переместиться.':'Выберите бойца и коснитесь противника в радиусе действия.'):'Противники выбирают цель и атакуют.';
 }
 function onTile(x,y){if(state.phase!=='hero'||busy)return;let unit=at(x,y),u=selectedUnit();if(unit&&state.heroes.includes(unit)){selected=unit.id;render();return}if(!u){note('Сначала выберите бойца отряда');return}if(state.used[u.id]){note(`${u.name} уже действовал в этом ходу`);return}if(action==='move'){if(canMove(x,y,u)){u.x=x;u.y=y;state.used[u.id]=true;addLog(`${u.name} перемещается по полю.`);action='attack';save();render();checkWin()}else note('Эта клетка недоступна');return}if(unit&&state.enemies.includes(unit)){if(action==='attack')attack(u,unit,false);else if(action==='skill')skill(u,unit);else note('Выберите действие «Удар» или «Умение»');return}if(action==='wait'){state.defending[u.id]=true;state.used[u.id]=true;addLog(`${u.name} принимает защитную стойку.`);save();render();return}if(action==='attack'||action==='skill')note('Коснитесь противника в пределах досягаемости')}
-function attack(attacker,target,isEnemy){if(distance(attacker,target)>attacker.range){note('Противник слишком далеко');return}let dmg=attacker.atk+Math.floor(Math.random()*3);if(state.defending[target.id]){dmg=Math.max(1,Math.floor(dmg/2));delete state.defending[target.id]}target.hp=Math.max(0,target.hp-dmg);addLog(`${attacker.name} наносит ${target.name} ${dmg} урона${target.hp===0?' — противник повержен':''}.`);if(!isEnemy)state.used[attacker.id]=true;save();render();if(!checkWin()&&target.hp===0)toast('Противник повержен')}
+function attack(attacker,target,isEnemy){if(distance(attacker,target)>attacker.range){note('Противник слишком далеко');return}let dmg=attacker.atk+Math.floor(Math.random()*3);if(state.defending[target.id]){dmg=Math.max(1,Math.floor(dmg/2));delete state.defending[target.id]}target.hp=Math.max(0,target.hp-dmg);tone(isEnemy?220:390);addLog(`${attacker.name} наносит ${target.name} ${dmg} урона${target.hp===0?' — противник повержен':''}.`);if(!isEnemy)state.used[attacker.id]=true;save();render();if(!checkWin()&&target.hp===0)toast('Противник повержен')}
 function skill(u,target){if(distance(u,target)>u.range){note('Цель вне радиуса умения');return}if(u.id==='bryn'){let dmg=u.atk+5;target.hp=Math.max(0,target.hp-dmg);u.hp=Math.min(u.max,u.hp+4);addLog(`Брин проводит щитовой натиск: ${dmg} урона и +4 здоровья.`)}else if(u.id==='lyra'){let dmg=u.atk+6;target.hp=Math.max(0,target.hp-dmg);addLog(`Лира выпускает меткий выстрел: ${dmg} урона.`)}else{let dmg=u.atk+4;target.hp=Math.max(0,target.hp-dmg);let other=aliveEnemies().filter(e=>e!==target&&distance(e,target)<=1)[0];if(other){other.hp=Math.max(0,other.hp-4);addLog(`Орен высвобождает искру руны: ${dmg} урона и цепной разряд!`)}else addLog(`Орен высвобождает искру руны: ${dmg} урона.`)}state.used[u.id]=true;action='attack';save();render();checkWin()}
 function setAction(a){action=a;render();if(a==='move')note('Выберите подсвеченную клетку для перемещения');else if(a==='skill')note(selectedUnit()?.skill||'Выберите умение')}
 document.querySelectorAll('.action').forEach(b=>b.onclick=()=>{if(state.phase!=='hero')return;if(!selectedUnit()){note('Выберите бойца');return}if(state.used[selected]){note('Этот боец уже действовал');return}setAction(b.dataset.action)});
 function neighbors(x,y){return [[x+1,y],[x-1,y],[x,y+1],[x,y-1]].filter(([a,b])=>a>=0&&a<W&&b>=0&&b<H&&state.terrain[b*W+a]!=='obstacle'&&state.terrain[b*W+a]!=='water')}

