node --input-type=module <<'JS'
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(`${runtime}/package.json`);
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(`${runtime}/linux.json`,'utf8'));
process.env.DISPLAY ||= ':'+readFileSync(`${runtime}/display`,'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
try {
 const context=await browser.newContext({viewport:{width:390,height:680},serviceWorkers:'allow'});
 const page=await context.newPage();
 let response;
 for(let attempt=0;attempt<30;attempt++) {
  try { response=await page.goto('http://127.0.0.1:3000/',{waitUntil:'networkidle',timeout:3000}); if(response?.ok()) break; }
  catch { if(attempt===29) throw Error('Preview server unavailable'); }
  await new Promise(resolve=>setTimeout(resolve,300));
 }
 await page.evaluate(async()=>{if('serviceWorker' in navigator){await navigator.serviceWorker.ready;}});
 await page.reload({waitUntil:'networkidle'});
 const result=await page.evaluate(()=>({height:innerHeight,query:matchMedia('(max-height:720px)').matches,font:getComputedStyle(document.querySelector('.unit .avatar')).fontSize,media:[...document.styleSheets[0].cssRules].filter(r=>r.conditionText?.includes('max-height')).map(r=>r.cssText.slice(0,120)),cache:undefined,controller:!!navigator.serviceWorker?.controller}));
 console.log(JSON.stringify(result));
 if(!result.query||result.font!=='22px') throw Error('Short viewport avatar CSS did not apply');
 mkdirSync('screenshots',{recursive:true});
 await page.screenshot({path:'screenshots/mobile.jpg',type:'jpeg',quality:68,fullPage:true});
 await context.setOffline(true);
 await page.reload({waitUntil:'load',timeout:10000});
 console.log('Offline reload:',await page.title());
 await context.close();
} finally { await browser.close(); }
